import{_ as o,o as t,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年8月2日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-02.md","filePath":"science-log/src/reconstructed/2026-08-02.md"}'),g={name:"science-log/src/reconstructed/2026-08-02.md"};function e(a,r,i,l,p,c){return t(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年8月2日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月2日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月2日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月2日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-06 依 CrossRef / arXiv <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 检索说明：2026-08-02 为<strong>周日</strong>。CrossRef 按 <code>from-pub-date=until-pub-date=2026-08-02</code> 检索，<strong>Nature（0028-0836）命中 0 条、Science（10.1126）命中 0 条</strong>，即当日无出版日条目；故科学 5 篇取自<strong>紧邻窗口（2026-07-30 ~ 2026-08-04）内的真实命中</strong>——Science 2026-07-30（2 篇）、Science Advances 2026-07-31（1 篇）、PNAS 2026-08-03 / 08-04（各 1 篇）。AI 5 篇严格取自 arXiv <code>submittedDate:[202608020000 TO 202608022359]</code> 的真实条目。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv（cs.AI，命中 30 篇）｜ 重建日：2026-11-06</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧪-用氟化钾做「appel-氟化」-醇到烷基氟的催化通用路线" tabindex="-1">🧪 用氟化钾做「Appel 氟化」：醇到烷基氟的催化通用路线 <a class="header-anchor" href="#🧪-用氟化钾做「appel-氟化」-醇到烷基氟的催化通用路线" aria-label="Permalink to &quot;🧪 用氟化钾做「Appel 氟化」：醇到烷基氟的催化通用路线&quot;">​</a></h3><p><strong>Catalytic Appel fluorination of alcohols with potassium fluoride</strong><em>Science（2026）</em></p><p>Appel 反应（PPh₃/CX₄ 把醇变卤代烃）是实验室最常见的羟基替换手段，但<strong>唯独做不了氟化物</strong>：氟离子会被磷试剂螯合成<strong>二氟膦烷（difluorophosphorane）<strong>而彻底失活，所以烷基氟长期依赖 DAST、Deoxo-Fluor 这类危险、昂贵且官能团兼容性差的试剂。Mondal A、Struijs J、Doyle C 等 <strong>12 位作者</strong>换成另一条磷化学路径：先做成</strong>台式稳定（bench-stable）的新戊氧基膦盐（neopentoxyphosphonium salts）</strong>，在<strong>氢键相转移催化</strong>下让廉价的 <strong>KF</strong> 完成氟化。机理关键是一个<strong>新戊氧基氟膦烷</strong>中间体，它与醇底物发生<strong>可逆交换</strong>，且该交换<strong>优先于二氟膦烷的生成</strong>——把「氟被磷吃掉」这一死结绕开；催化剂同时负责<strong>增溶 KF</strong> 与<strong>促 P–F 键解离</strong>。由于取代走的是可逆的烷氧基交换，这条路线理论上可延伸到<strong>醇的对映选择性氟化</strong>，而烷基氟正是现代药物化学里提高代谢稳定性、以及 ¹⁸F PET 示踪的核心基团。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aec6298" target="_blank" rel="noreferrer">10.1126/science.aec6298</a></p><h3 id="🩸-血红素合成的负反馈被补全-poldip2-是线粒体蛋白酶-clpxp-的血红素感应接头" tabindex="-1">🩸 血红素合成的负反馈被补全：POLDIP2 是线粒体蛋白酶 CLPXP 的血红素感应接头 <a class="header-anchor" href="#🩸-血红素合成的负反馈被补全-poldip2-是线粒体蛋白酶-clpxp-的血红素感应接头" aria-label="Permalink to &quot;🩸 血红素合成的负反馈被补全：POLDIP2 是线粒体蛋白酶 CLPXP 的血红素感应接头&quot;">​</a></h3><p><strong>An adaptor for feedback regulation of heme biosynthesis by a mitochondrial protease</strong><em>Science（2026）</em></p><p>血红素合成必须<strong>既不缺、也不溢</strong>：不足则铁利用与呼吸链受损，过量则积累有毒卟啉并耗竭细胞铁。已知血红素会诱导血红素合成限速酶 <strong>ALAS</strong> 经线粒体酪蛋白水解酶复合体 <strong>CLPX–CLPP（CLPXP）<strong>降解，但「血红素如何被读成降解信号」一直是缺口。Cottle T、Joh L、Posner C 等 <strong>8 位作者</strong>找出 <strong>POLDIP2</strong> 就是这个</strong>血红素感应接头（heme-sensing adaptor）</strong>：它<strong>足以在体外重建</strong> ALAS 的负反馈降解，说明不需要额外因子；在细胞里 POLDIP2 是 ALAS 周转所必需，并在<strong>红系分化</strong>过程中调节血红素产量；生化上 POLDIP2 <strong>直接识别并结合血红素结合的 ALAS</strong>，把它递送给 CLPXP；降解的<strong>起始</strong>还需要 ALAS 的<strong>羧基端元件</strong>。这条链把「代谢物浓度 → 接头识别 → 蛋白酶降解 → 通量下调」的闭环补完整，也让 POLDIP2 这个原本以 NADPH 氧化酶相关功能知名的蛋白多了一层代谢感应角色。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.ads5397" target="_blank" rel="noreferrer">10.1126/science.ads5397</a></p><h3 id="🪐-海王星的内卫星与环是「冰质天体内部」的裸露残骸-jwst-抓到-2-72-μm-富镁层状硅酸盐" tabindex="-1">🪐 海王星的内卫星与环是「冰质天体内部」的裸露残骸：JWST 抓到 2.72 μm 富镁层状硅酸盐 <a class="header-anchor" href="#🪐-海王星的内卫星与环是「冰质天体内部」的裸露残骸-jwst-抓到-2-72-μm-富镁层状硅酸盐" aria-label="Permalink to &quot;🪐 海王星的内卫星与环是「冰质天体内部」的裸露残骸：JWST 抓到 2.72 μm 富镁层状硅酸盐&quot;">​</a></h3><p><strong>Neptune&#39;s inner moons and rings are exposed icy body interiors</strong><em>Science Advances（2026）</em></p><p>海王星只有一颗大卫星 Triton（逆行、几乎确定是被捕获的柯伊伯带天体），此外还有一串尘埃环与小卫星，其成分与来源长期不明。Davis M、Belyakov M、Wong I 等 <strong>5 位作者</strong>用 <strong>JWST</strong> 观测了环以及 <strong>Larissa、Galatea、Proteus</strong> 三颗内卫星。结果有三点值得记住：其一，它们的光谱<strong>与外太阳系其他天体明显不同</strong>；其二，<strong>没有水冰的证据</strong>，却有很深的 <strong>3 μm OH 吸收带</strong>——说明水以含水矿物而非冰的形式存在；其三，Larissa、Galatea 与环出现了外太阳系天体里<strong>独一无二</strong>的 <strong>2.72 μm 吸收带</strong>，这是<strong>富镁层状硅酸盐（Mg-phyllosilicate）<strong>的诊断特征，而层状硅酸盐是</strong>广泛水蚀变</strong>的路标。合理解释是：这些物质<strong>原本形成于原始卫星的内部</strong>（那里有液态水与岩石反应的条件），那些卫星在 <strong>Triton 被捕获时的剧烈碰撞或潮汐撕裂</strong>中碎掉，才把内部物质暴露到环与表层。这把 Triton 捕获假说的证据从轨道动力学扩展到了<strong>矿物学</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aeb1437" target="_blank" rel="noreferrer">10.1126/sciadv.aeb1437</a></p><h3 id="🍽-agrp-神经元是-glp-1-受体激动剂减重效应的「必要条件」-雌鼠" tabindex="-1">🍽 AgRP 神经元是 GLP-1 受体激动剂减重效应的「必要条件」（雌鼠） <a class="header-anchor" href="#🍽-agrp-神经元是-glp-1-受体激动剂减重效应的「必要条件」-雌鼠" aria-label="Permalink to &quot;🍽 AgRP 神经元是 GLP-1 受体激动剂减重效应的「必要条件」（雌鼠）&quot;">​</a></h3><p><strong>AgRP neurons are required for the weight-lowering effects of GLP-1 receptor agonists in female mice</strong><em>PNAS（2026）</em></p><p>按教科书框架，弓状核 <strong>AgRP 神经元</strong>是「饥饿神经元」：负能量平衡时被激活，促摄食、降能耗。由此自然推论——司美格鲁肽这类 <strong>GLP-1 受体激动剂（GLP-1RA）<strong>要减重，就该</strong>抑制或绕过</strong> AgRP 神经元。d&#39;Ávila M、Cavalcanti-de-Albuquerque J、Collado-Pérez R 等 <strong>9 位作者</strong>得到的结论<strong>正好相反</strong>：在多种 <strong>AgRP 功能缺失模型</strong>里，破坏 AgRP 环路完整性会<strong>削弱 GLP-1RA 的完整减重效果</strong>，也就是说 AgRP 神经元的<strong>激活</strong>是这一效应<strong>充分展开所必需</strong>的。作者进一步指出这种必要性<strong>随性别、饮食和 AgRP 干预方式而变化</strong>——在雌鼠中最清晰，这与临床上女性对 GLP-1RA 反应差异的现象相呼应。意义在两层：<strong>机制上</strong>，长期疗效不是单纯的「关掉饥饿神经元」，而依赖 AgRP 环路参与重塑能量平衡；<strong>方法上</strong>，它提示 AgRP 环路活性可能成为疗效的<strong>预测性标志</strong>，也提醒肥胖药理研究不能只用雄鼠单一模型。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2614476123" target="_blank" rel="noreferrer">10.1073/pnas.2614476123</a></p><h3 id="🧠-把「脑龄」从标量变成图谱-体素级局部脑龄模型-14-748-名认知正常者" tabindex="-1">🧠 把「脑龄」从标量变成图谱：体素级局部脑龄模型（14,748 名认知正常者） <a class="header-anchor" href="#🧠-把「脑龄」从标量变成图谱-体素级局部脑龄模型-14-748-名认知正常者" aria-label="Permalink to &quot;🧠 把「脑龄」从标量变成图谱：体素级局部脑龄模型（14,748 名认知正常者）&quot;">​</a></h3><p><strong>Deep learning maps local brain aging in relation to cognition across human adulthood</strong><em>PNAS（2026）</em></p><p>「脑龄」通常被压成一个<strong>全局数值（GBA）</strong>，方便但粗暴：大脑老化在皮层各区的速度并不相同，而<strong>阿尔茨海默病（AD）最相关的正是区域性的脆弱</strong>，单一标量会把这种空间信息抹平。Chaudhari N、Vega Huerta O、Bhattacharya S 等 <strong>6 位作者</strong>训练了一个<strong>体素级</strong>深度网络，在来自多中心的 <strong>14,748 名认知正常（CN）参与者</strong>的 <strong>T1 加权 MRI</strong> 上估计<strong>局部脑龄（LBA）</strong>。结果给出稳定的空间格局：<strong>额叶与颞叶相对「更老」</strong>，顶叶与枕叶相对「更年轻」。在 <strong>1,102 名 CN 老年人</strong>的追踪中，前颞叶等区域呈现<strong>渐进性超前老化</strong>，并与认知表现关联——这正是 AD 病理最早累积的地带。价值在于把脑龄从<strong>一个数字变成一张图</strong>：既提供单个受试者的区域化偏差，也为「AD 前期在哪些皮层区域先失守」提供可量化的影像学指标。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2532233123" target="_blank" rel="noreferrer">10.1073/pnas.2532233123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧠-v-mem-按「模态路由」检索的长期多模态智能体记忆" tabindex="-1">🧠 V-Mem：按「模态路由」检索的长期多模态智能体记忆 <a class="header-anchor" href="#🧠-v-mem-按「模态路由」检索的长期多模态智能体记忆" aria-label="Permalink to &quot;🧠 V-Mem：按「模态路由」检索的长期多模态智能体记忆&quot;">​</a></h3><p><strong>V-Mem: Modality-Routed Retrieval for Long-Term Multimodal Agentic Memory</strong><em>arXiv（2026）</em></p><p>现有智能体记忆几乎都建立在<strong>文本</strong>上，少数支持多模态的系统在<strong>视觉相关提问</strong>上依旧失败。Kang Dingyi、Jiang Dongming、Li Yi、Li Guanpeng 等 <strong>5 位作者</strong>把失败原因定位到相似度检索的隐含假设——「在索引空间里，查询靠近能回答它的证据」。多模态下有<strong>两道裂缝</strong>：<strong>模态鸿沟（modality gap）</strong>——即使在联合嵌入空间里，查询也更靠近<strong>同模态</strong>内容而非异模态证据；<strong>相似–相关鸿沟</strong>——最相似的内容常常<strong>不是</strong>回答问题所需的那条证据，当查询同时含文本与图像时最严重。<strong>V-Mem</strong> 的解法是<strong>按模态路由</strong>：先从查询本身判断<strong>目标证据的模态</strong>，把对话组织成「轮（round）」，<strong>只在与匹配项同一轮内</strong>取回目标模态内容，从而<strong>完全避免跨模态比较</strong>；再用 <strong>LLM 生成的锚点</strong>（纯文本查图像时用「假想图注」，需图文联合时用「查询文本 + 从查询图像抽出的关键词」）去贴近证据。在 <strong>Mem-Gallery</strong> 上 LLM 判分 <strong>0.82</strong>（次优 0.56），带图问题 <strong>0.87</strong>（所有基线不超过 0.47）；<strong>LoCoMo</strong> 上 0.69 对 0.58。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.01543" target="_blank" rel="noreferrer">2608.01543</a></p><h3 id="📈-以题生题-qbq-给竞赛数学的强化微调装上自演化课程" tabindex="-1">📈 以题生题（QbQ）：给竞赛数学的强化微调装上自演化课程 <a class="header-anchor" href="#📈-以题生题-qbq-给竞赛数学的强化微调装上自演化课程" aria-label="Permalink to &quot;📈 以题生题（QbQ）：给竞赛数学的强化微调装上自演化课程&quot;">​</a></h3><p><strong>Question Begets Question: Self-Evolving Curriculum for Reinforcement Fine-Tuning on Competition Mathematics</strong><em>arXiv（2026）</em></p><p>教模型一项它尚未掌握的技能，卡在三处：<strong>数据稀缺</strong>、<strong>没有可信的推理轨迹（oracle reasoning）</strong>、以及<strong>明显的能力天花板</strong>——继续加数据收益归零。Bao Longtian、Wang Jianyou、Zhang Yang、Zheng Youze 等 <strong>5 位作者</strong>在受控设定里训练 <strong>Qwen2.5-Math-7B</strong> 做 <strong>AIME</strong>，该模型初始 <strong>pass@1 仅 5.6%</strong>。对策是 <strong>Question-begets-Question（QbQ）</strong>：由教师把已有题目<strong>改写为多样变体</strong>，探同一组底层技能，从而规模化造数据；同时<strong>只用题面与最终答案做强化学习</strong>，<strong>从不使用教师的推理轨迹</strong>——绕开「教师推理本身可能就是错的」这一隐患。关键发现是：<strong>静态训练</strong>（无论真实数据加合成数据、还是不做课程调度的 QbQ 数据）都会<strong>在远未达到目标处平台化</strong>，收益来自<strong>自演化的课程调度</strong>：随模型变强，题目难度与技能覆盖同步推进。这为「合成数据的关键不在数量而在<strong>难度编排</strong>」提供了干净证据。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.01522" target="_blank" rel="noreferrer">2608.01522</a></p><h3 id="🔓-minegrad-只上传-lora-梯度也不安全——联邦微调的解析式梯度反演攻击" tabindex="-1">🔓 MineGrad：只上传 LoRA 梯度也不安全——联邦微调的解析式梯度反演攻击 <a class="header-anchor" href="#🔓-minegrad-只上传-lora-梯度也不安全——联邦微调的解析式梯度反演攻击" aria-label="Permalink to &quot;🔓 MineGrad：只上传 LoRA 梯度也不安全——联邦微调的解析式梯度反演攻击&quot;">​</a></h3><p><strong>MineGrad: Gradient Inversion Attacks on LoRA Fine-Tuning</strong><em>arXiv（2026）</em></p><p><strong>参数高效微调（PEFT）<strong>已被搬进</strong>联邦学习</strong>以省通信与算力：用户先下载预训练模型，本地只训<strong>轻量 LoRA 模块</strong>、主干冻结，<strong>只把 LoRA 参数的梯度</strong>上传服务器。直觉是「共享的参数很少，泄露应该也少」。Sami Hasin Us、Sen Swapneel、Guler Basak <strong>3 位作者</strong>证明这个直觉不成立：他们考虑<strong>恶意服务器</strong>——它可以<strong>篡改训练协议</strong>，具体做法是先给出一个<strong>被动过手脚（poisoned）的预训练模型</strong>，再结合收到的 LoRA 梯度，构造一个<strong>解析式（analytical）攻击</strong>，<strong>直接把私有训练数据反解出来</strong>。攻击的核心设计是<strong>让微调数据被「嵌进」上传的梯度里</strong>，从而可以解析重建而非靠迭代优化猜。这提醒两件事：一是「共享信息量小」不等于「隐私风险小」，梯度的<strong>信息密度</strong>取决于服务端能否<strong>预先操纵</strong>模型状态；二是 LoRA 在联邦场景下需要重新做威胁建模——防御不能只盯着梯度加噪，还要能<strong>验证下发的基座模型未被污染</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.01521" target="_blank" rel="noreferrer">2608.01521</a></p><h3 id="🕳-denialrag-单文档投毒的新花样——把正确答案「点名然后否认」" tabindex="-1">🕳 DenialRAG：单文档投毒的新花样——把正确答案「点名然后否认」 <a class="header-anchor" href="#🕳-denialrag-单文档投毒的新花样——把正确答案「点名然后否认」" aria-label="Permalink to &quot;🕳 DenialRAG：单文档投毒的新花样——把正确答案「点名然后否认」&quot;">​</a></h3><p><strong>DenialRAG: Single-Document RAG Poisoning via Embedded Parametric Denial</strong><em>arXiv（2026）</em></p><p><strong>RAG 语料投毒</strong>的威胁模型很干净：攻击者只需往检索库里塞<strong>一篇</strong>精心构造的文档，就能把 LLM 引向攻击者选定的错误答案。以往的单文档攻击有个共同的自我约束——<strong>避免在毒文档里明确点出正确答案并反驳它</strong>。Zhurekbay Abay、Liu Tao、Li Fan <strong>3 位作者</strong>反过来设计 <strong>DenialRAG</strong>：在同一段被检索到的文字里<strong>先点名正确答案、随即否认它</strong>，再给出一套攻击者控制的<strong>解释</strong>去支持错误答案。这样做的机理优势是把**「正确 vs 错误」的冲突直接内嵌进生成器看到的上下文**：模型不再需要「因为缺失正确信息而漂移」，而是被诱导<strong>在已有正确信息在场的情况下主动放弃它</strong>——这恰好利用了大模型对「叙述连贯、有解释」的偏好。评测覆盖<strong>三个开放域问答数据集、四家厂商的八个目标 LLM、五种推理期防御</strong>，并与四篇已发表的单文档投毒攻击对比。对任何靠检索增强的知识库系统（包括本知识库）而言，结论是：<strong>检索命中正确文档并不能保证答案正确</strong>，防御必须落到「答案与证据的一致性核验」而非「检索质量」。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.02678" target="_blank" rel="noreferrer">2608.02678</a></p><h3 id="✅-用-lean-4-自动判定「新颖性」-能编译不等于新-也不等于对" tabindex="-1">✅ 用 Lean 4 自动判定「新颖性」：能编译不等于新，也不等于对 <a class="header-anchor" href="#✅-用-lean-4-自动判定「新颖性」-能编译不等于新-也不等于对" aria-label="Permalink to &quot;✅ 用 Lean 4 自动判定「新颖性」：能编译不等于新，也不等于对&quot;">​</a></h3><p><strong>Beyond Correctness: Toward Automated Novelty Verification with Lean 4</strong><em>arXiv（2026）</em></p><p>AI 做数学目前只保证<strong>正确性</strong>，不保证<strong>新颖性</strong>：一个自动生成的定理可以在 <strong>Lean</strong> 里零错误编译，却是<strong>早已被证明过的结果</strong>。Porto Ayrton（<strong>单人作者</strong>）给出流水线 <strong>AViD Journal</strong>：输入一篇 <strong>LaTeX</strong> 论文，把其中的命题<strong>形式化到 Lean 4</strong>，然后用一棵<strong>三维决策树</strong>给出新颖性裁决——① <strong>是否已存在</strong>：查形式语料库 <strong>Mathlib</strong> 与非形式库 <strong>TheoremSearch / Matlas</strong>（带时间过滤 + LLM 判官）；② <strong>是否非平凡</strong>：用<strong>自动 tactic</strong> 尝试能否被平凡解决；③ <strong>证明的结构距离</strong>：以<strong>前提集合（premise set）的 Jaccard 距离</strong>衡量与已有证明的接近程度。评估用的是<strong>因声明重复而被 arXiv 撤稿</strong>的论文。作者诚实地报告，比任何性能数字更有价值的是<strong>三个与实现无关的障碍</strong>：<strong>Lean 编译成功不代表语义保真</strong>（形式化可能偷换了原意）；<strong>召回率上限由定理索引的覆盖度决定</strong>，而非相似度度量；<strong>arXiv 撤稿时会删除源码</strong>，导致任何基于撤稿论文的基准都<strong>不可复现</strong>。这三点恰好也是「用形式化做 AI 科学审查」这条路线必须先在工程上解决的前置条件。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.14669" target="_blank" rel="noreferrer">2608.14669</a></p><blockquote><p>📅 日期：2026-08-02 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const m=o(g,[["render",e]]);export{d as __pageData,m as default};
